    seen = {}
    api.submit("alice", lambda d: seen.setdefault("d", d))
    assert seen["d"]["batch_size"] == 20
    assert seen["d"]["owner"] == "alice"


def test_custom_batch_size():
    seen = {}
    api.submit("bob", lambda d: seen.setdefault("d", d), batch_size=42)
    assert seen["d"]["batch_size"] == 42
    assert seen["d"]["owner"] == "bob"


def test_invalid_before_enqueue():
    calls = []
    api.submit("carol", lambda d: calls.append(d), batch_size=0)
    assert calls == []
    api.submit("dave", lambda d: calls.append(d), batch_size=101)
    assert calls == []
    api.submit("erin", lambda d: calls.append(d), batch_size=-5)
    assert calls == []


